import React, { useState, useEffect } from 'react';
import { 
  Clock, 
  ExternalLink, 
  Image as ImageIcon, 
  Loader2, 
  RefreshCw,
  AlertCircle 
} from 'lucide-react';
import { formatDistanceToNow } from 'date-fns';
import { zhCN } from 'date-fns/locale';

const NewsList = ({ category, refreshTrigger }) => {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [lastUpdate, setLastUpdate] = useState(null);
  const [isDemoMode, setIsDemoMode] = useState(false);
  const [systemStatus, setSystemStatus] = useState(null);

  // 优化的缓存机制，避免重复请求
  const [cache, setCache] = useState(new Map());
  const [pendingRequests, setPendingRequests] = useState(new Set());
  const CACHE_DURATION = 5 * 60 * 1000; // 5分钟缓存

  // AbortController用于取消进行中的请求
  const [abortController, setAbortController] = useState(null);

  // 图片URL验证函数
  const isValidImageUrl = (url) => {
    if (!url || typeof url !== 'string') return false;

    // 检查是否为有效的图片URL
    const imageExtensions = /\.(jpg|jpeg|png|gif|webp|svg)(\?.*)?$/i;
    const validHosts = ['images.unsplash.com', 'cdn.pixabay.com', 'picsum.photos', 'via.placeholder.com'];

    try {
      const urlObj = new URL(url);
      return imageExtensions.test(url) || validHosts.includes(urlObj.hostname);
    } catch {
      return false;
    }
  };

  // 获取安全的图片URL
  const getSafeImageUrl = (originalUrl) => {
    if (isValidImageUrl(originalUrl)) {
      return originalUrl;
    }
    return '/placeholder-image.svg';
  };

  // 检查缓存
  const getCachedData = (cacheKey) => {
    const cached = cache.get(cacheKey);
    if (cached && (Date.now() - cached.timestamp) < CACHE_DURATION) {
      return cached.data;
    }
    return null;
  };

  // 设置缓存
  const setCachedData = (cacheKey, data) => {
    const newCache = new Map(cache);
    newCache.set(cacheKey, {
      data,
      timestamp: Date.now()
    });
    setCache(newCache);
  };

  const fetchNews = async (pageNum = 1, isRefresh = false) => {
    try {
      setLoading(true);
      setError(null);

      const params = new URLSearchParams({
        page: pageNum.toString(),
        limit: '10'
      });

      if (category !== '全部') {
        params.append('category', category);
      }

      const cacheKey = `${category}_${pageNum}`;

      // 检查缓存（只在非强制刷新时使用）
      if (!isRefresh) {
        const cachedData = getCachedData(cacheKey);
        if (cachedData) {
          console.log('使用缓存数据:', cacheKey);
          if (isRefresh || pageNum === 1) {
            setNews(cachedData.data);
          } else {
            setNews(prev => [...prev, ...cachedData.data]);
          }
          setHasMore(cachedData.data.length === 10);
          setLoading(false);
          return;
        }
      }

      // 检查是否有相同的请求正在进行
      const requestKey = `${cacheKey}_${isRefresh}`;
      if (pendingRequests.has(requestKey)) {
        console.log('请求已在进行中，跳过:', requestKey);
        return;
      }

      // 取消之前的请求
      if (abortController) {
        abortController.abort();
      }

      // 创建新的AbortController
      const controller = new AbortController();
      setAbortController(controller);
      setPendingRequests(prev => new Set([...prev, requestKey]));

      const response = await fetch(`/api/news/latest?${params}`, {
        signal: controller.signal
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      if (data.success) {
        const newsData = data.data.data;

        // 数据清洗：验证和修复图片URL
        const cleanedData = newsData.map(item => ({
          ...item,
          imageUrl: getSafeImageUrl(item.imageUrl)
        }));

        // 设置缓存
        setCachedData(cacheKey, {
          data: cleanedData
        });

        if (isRefresh || pageNum === 1) {
          setNews(newsData);
        } else {
          setNews(prev => [...prev, ...newsData]);
        }
        setHasMore(newsData.length === 10);
        setLastUpdate(new Date());

        // 检测是否在演示模式（检查新闻ID是否以demo_开头）
        const hasDemoData = newsData.some(item => item.id && item.id.startsWith('demo_'));
        setIsDemoMode(hasDemoData);
      } else {
        throw new Error(data.error || '获取新闻失败');
      }
    } catch (err) {
      if (err.name === 'AbortError') {
        console.log('请求被取消:', err.message);
        return;
      }
      console.error('获取新闻失败:', err);
      setError(err.message);
    } finally {
      setLoading(false);
      setPendingRequests(prev => {
        const newSet = new Set(prev);
        const requestKey = `${category}_${pageNum}_${isRefresh}`;
        newSet.delete(requestKey);
        return newSet;
      });
    }
  };

  // 初始加载和分类/刷新触发
  useEffect(() => {
    setPage(1);
    fetchNews(1, true);
  }, [category, refreshTrigger]);

  // 清理函数：组件卸载时取消请求
  useEffect(() => {
    return () => {
      if (abortController) {
        abortController.abort();
      }
    };
  }, [abortController]);

  const loadMore = () => {
    if (!loading && hasMore) {
      const nextPage = page + 1;
      setPage(nextPage);
      fetchNews(nextPage);
    }
  };

  const getCategoryColor = (category) => {
    const colors = {
      'AI新闻': 'bg-blue-100 text-blue-700',
      'AI框架': 'bg-green-100 text-green-700',
      '新算法': 'bg-purple-100 text-purple-700',
      '新思路': 'bg-yellow-100 text-yellow-700',
      '新工具': 'bg-pink-100 text-pink-700',
      '全部': 'bg-gray-100 text-gray-700'
    };
    return colors[category] || 'bg-gray-100 text-gray-700';
  };

  if (loading && news.length === 0) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-8 h-8 animate-spin text-blue-600 mr-2" />
        <span className="text-gray-600">加载AI资讯中...</span>
      </div>
    );
  }

  if (error && news.length === 0) {
    return (
      <div className="text-center py-12">
        <AlertCircle className="w-12 h-12 text-amber-500 mx-auto mb-4" />
        <h3 className="text-lg font-medium text-gray-900 mb-2">数据源连接中</h3>
        <p className="text-gray-600 mb-4">
          {error.includes('ERR_INTERNET_DISCONNECTED') ? (
            <>
              系统正在初始化数据源，请稍候...
              <br />
              <small className="text-gray-500 mt-2 block">
                如果长时间没有数据，可能是网络环境配置问题
              </small>
            </>
          ) : (
            error
          )}
        </p>
        <button
          onClick={() => fetchNews(1, true)}
          className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <RefreshCw className="w-4 h-4 mr-2" />
          重新连接
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* 页面头部 */}
      <div className="space-y-4">
        {/* 演示模式提示 */}
        {isDemoMode && (
          <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-4">
            <div className="flex items-center space-x-3">
              <AlertCircle className="w-5 h-5 text-yellow-600 flex-shrink-0" />
              <div className="flex-1">
                <h3 className="text-sm font-medium text-yellow-800">
                  当前为演示模式
                </h3>
                <p className="text-sm text-yellow-700 mt-1">
                  系统正在尝试连接真实RSS源，当前显示示例数据。您可以手动刷新尝试获取最新资讯。
                  {systemStatus && (
                    <span className="block mt-1 text-xs">
                      最后更新: {systemStatus.lastUpdate ? 
                        formatDistanceToNow(new Date(systemStatus.lastUpdate), { addSuffix: true, locale: zhCN }) 
                        : '未知'}
                    </span>
                  )}
                </p>
              </div>
              <button
                onClick={() => fetchNews(1, true)}
                className="flex items-center space-x-1 px-3 py-1.5 bg-yellow-100 text-yellow-800 rounded-md hover:bg-yellow-200 transition-colors text-sm"
              >
                <RefreshCw className="w-4 h-4" />
                <span>重新获取</span>
              </button>
            </div>
          </div>
        )}

        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold text-gray-900">
              {category === '全部' ? '最新AI资讯' : `${category}资讯`}
            </h2>
            {lastUpdate && (
              <p className="text-sm text-gray-500 mt-1">
                最后更新: {formatDistanceToNow(lastUpdate, { addSuffix: true, locale: zhCN })}
              </p>
            )}
          </div>

          <div className="flex items-center space-x-2">
            <span className={`px-3 py-1 rounded-full text-xs font-medium ${getCategoryColor(category)}`}>
              {category}
            </span>
            <span className="text-sm text-gray-500">
              共 {news.length} 条
            </span>
          </div>
        </div>
      </div>

      {/* 新闻列表 - 使用优化的网格布局 */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-3 gap-6">
        {news.map((item) => (
          <article
            key={item.id}
            className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 hover:shadow-md transition-shadow h-full flex flex-col"
          >
            {/* 图片 */}
            <div className="mb-4">
              <img
                src={item.imageUrl || '/placeholder-image.svg'}
                alt=""
                className="w-full h-40 object-cover rounded-lg"
                onError={(e) => {
                  e.target.src = '/placeholder-image.svg';
                }}
              />
            </div>

            <div className="flex-1 flex flex-col">
                {/* 标题和链接 */}
                <h3 className="text-lg font-semibold text-gray-900 mb-2 line-clamp-2">
                  <a
                    href={item.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="hover:text-blue-600 transition-colors"
                  >
                    {item.title}
                  </a>
                </h3>

                {/* 描述 */}
                {item.description && (
                  <p className="text-gray-600 mb-3 line-clamp-3">
                    {item.description}
                  </p>
                )}

                {/* 元信息 */}
                <div className="mt-auto pt-4 border-t border-gray-100">
                  <div className="flex items-center justify-between mb-3">
                    <div className="flex items-center space-x-2 text-sm text-gray-500">
                      <Clock className="w-4 h-4" />
                      <span>{formatDistanceToNow(new Date(item.publishedAt), { 
                        addSuffix: true, 
                        locale: zhCN 
                      })}</span>
                    </div>
                    <span className={`px-2 py-1 rounded-full text-xs font-medium ${getCategoryColor(item.category)}`}>
                      {item.category}
                    </span>
                  </div>

                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600">{item.source}</span>
                    <a
                      href={item.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center text-blue-600 hover:text-blue-700 transition-colors text-sm"
                    >
                      <ExternalLink className="w-4 h-4 mr-1" />
                      阅读原文
                    </a>
                  </div>
                </div>
            </div>
          </article>
        ))}
      </div>

      {/* 加载更多 */}
      {news.length > 0 && (
        <div className="text-center pt-6">
          {hasMore ? (
            <button
              onClick={loadMore}
              disabled={loading}
              className="inline-flex items-center px-6 py-3 bg-white border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-50 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  加载中...
                </>
              ) : (
                '加载更多'
              )}
            </button>
          ) : (
            <p className="text-gray-500">没有更多内容了</p>
          )}
        </div>
      )}

      {/* 空状态 */}
      {news.length === 0 && !loading && !error && (
        <div className="text-center py-12">
          <Loader2 className="w-12 h-12 text-gray-400 mx-auto mb-4 animate-spin" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">正在获取AI资讯...</h3>
          <p className="text-gray-600">
            系统正在从多个数据源获取最新的AI相关资讯
            <br />
            <small className="text-gray-500 mt-2 block">
              包括机器之心、ArXiv等权威来源
            </small>
          </p>
          <div className="mt-4">
            <div className="inline-flex items-center text-sm text-gray-500">
              <div className="w-2 h-2 bg-blue-600 rounded-full mr-2 animate-pulse"></div>
              实时更新中
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default NewsList;
